package com.sathavahana.kalamkari.controller; import com.sathavahana.kalamkari.dto.OrderDto; import com.sathavahana.kalamkari.service.OrderService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/orders") public class OrderController {private final OrderService service; public OrderController(OrderService s){service=s;} @GetMapping public List<OrderDto> list(){return service.list();} @PostMapping public OrderDto checkout(){return service.checkout();}}
